        let hash = ContentHash::of(source.as_bytes());
        let source_basis = SourceBasis {
            source: self.source,
            content_hash: hash,
        };
        let view = liminal_source::Utf8HolderView::from_bytes(source_basis, source.as_bytes())?;
        let cst = liminal_cst::parse(&view);
