            graph,
            diagnostics: resolve_diagnostics,
        } = resolve(&hir, &transient)?;
        let mut diagnostics = hir_diagnostics
            .into_iter()
            .map(Phase1Diagnostic::Hir)
            .collect::<Vec<_>>();
