 3351	        for (field, value) in [
 3352	            ("id", &attempt.id),
 3353	            ("attack_class", &attempt.attack_class),
 3354	            ("target", &attempt.target),
 3355	            ("attempt", &attempt.attempt),
 3356	            ("observed_result", &attempt.observed_result),
 3357	            ("classification", &attempt.classification),
 3358	        ] {
