 3447	                "{who}: attempt {:?} target coordinate must be a positive line number",
 3448	                attempt.id
 3449	            )
 3450	        })?;
 3451	        anyhow::ensure!(
 3452	            line > 0 && line <= target_source.lines().count().max(1),
