11652	/// Scan the implementation crates' non-test sources for concurrency
11653	/// primitives. A file's trailing `#[cfg(test)]` module is skipped; comment
11654	/// lines are skipped. Deterministic order: crates, files and lines sorted.
11655	fn scan_concurrency_primitives(root: &Utf8Path) -> Result<ConcurrencyScan> {
11656	    fn walk(dir: &Utf8Path, out: &mut Vec<Utf8PathBuf>) -> Result<()> {
11657	        let mut entries = fs::read_dir(dir.as_std_path())
11658	            .with_context(|| format!("read {dir}"))?
11659	            .map(|entry| entry.map(|e| e.path()))
11660	            .collect::<std::io::Result<Vec<_>>>()?;
11661	        entries.sort();
11662	        for path in entries {
11663	            let path = Utf8PathBuf::from_path_buf(path)
11664	                .map_err(|p| anyhow::anyhow!("non-UTF-8 path {}", p.display()))?;
11665	            if path.is_dir() {
11666	                walk(&path, out)?;
11667	            } else if path.extension() == Some("rs") {
11668	                out.push(path);
11669	            }
11670	        }
11671	        Ok(())
11672	    }
11673	    let mut scan = ConcurrencyScan {
11674	        execution: Vec::new(),
11675	        sync: Vec::new(),
11676	    };
11677	    let crates_dir = root.join("crates");
11678	    let mut crate_dirs = fs::read_dir(crates_dir.as_std_path())
11679	        .with_context(|| format!("read {crates_dir}"))?
11680	        .map(|entry| entry.map(|e| e.path()))
11681	        .collect::<std::io::Result<Vec<_>>>()?;
11682	    crate_dirs.sort();
11683	    for member in crate_dirs {
11684	        let member_dir = Utf8PathBuf::from_path_buf(member)
11685	            .map_err(|p| anyhow::anyhow!("non-UTF-8 path {}", p.display()))?;
11686	        let Some(name) = member_dir.file_name() else {
11687	            continue;
11688	        };
11689	        if CONCURRENCY_SCAN_EXCLUDED_CRATES.contains(&name) || !member_dir.join("src").is_dir() {
11690	            continue;
11691	        }
11692	        let manifest = member_dir.join("Cargo.toml");
11693	        if manifest.is_file() {
11694	            let external = runtime_external_dependencies(&manifest)?;
11695	            let unknown = external
11696	                .iter()
11697	                .filter(|dep| !CONCURRENCY_SCAN_ALLOWED_DEPENDENCIES.contains(&dep.as_str()))
11698	                .cloned()
11699	                .collect::<Vec<_>>();
11700	            anyhow::ensure!(
11701	                unknown.is_empty(),
11702	                "{name} depends on {unknown:?}, outside the closed list the \
11703	                 concurrency scan reasons about; a dependency may export a \
11704	                 macro that spawns, which a lexical scan cannot see. Decide, \
11705	                 then widen CONCURRENCY_SCAN_ALLOWED_DEPENDENCIES"
11706	            );
11707	        }
11708	        let mut files = Vec::new();
11709	        walk(&member_dir.join("src"), &mut files)?;
11710	        for file in files {
11711	            let text = fs::read_to_string(&file).with_context(|| format!("read {file}"))?;
11712	            let relative = file.strip_prefix(root).unwrap_or(&file);
11713	            // Blind pass 1 at 612cbcc (A06): this used to stop at the first
11714	            // `#[cfg(test)]` line, so production code after an earlier test
11715	            // module escaped the scan. The attributed item is skipped as a
11716	            // block (brace depth) or, for a brace-less item, through its `;`,
11717	            // and scanning resumes after it. F-56: braces used to be
11718	            // counted textually, strings and comments included, so an
11719	            // unbalanced brace inside a test module could end the skip late
11720	            // and hide a production spawn. Only structural braces count now,
11721	            // the same scanner the mutant anchor screen uses.
11722	            let mut skipping: Option<(usize, bool)> = None;
11723	            let mut scanner = SourceScanner::default();
11724	            for (index, line) in text.lines().enumerate() {
11725	                let trimmed = line.trim();
11726	                let structural = scanner.structural(line);
11727	                if let Some((depth, entered)) = skipping.as_mut() {
11728	                    *depth += structural.matches('{').count();
11729	                    let closes = structural.matches('}').count();
11730	                    if *depth > 0 {
11731	                        *entered = true;
11732	                    }
11733	                    *depth = depth.saturating_sub(closes);
11734	                    if (*entered && *depth == 0) || (!*entered && trimmed.ends_with(';')) {
11735	                        skipping = None;
11736	                    }
11737	                    continue;
11738	                }
11739	                if trimmed.replace(' ', "") == "#[cfg(test)]" {
11740	                    skipping = Some((0, false));
11741	                    continue;
11742	                }
11743	                if trimmed.starts_with("//") {
11744	                    continue;
11745	                }
11746	                for token in CONCURRENCY_EXECUTION_PRIMITIVES {
11747	                    if line.contains(token) {
11748	                        scan.execution
11749	                            .push(format!("{relative}:{}:{token}", index + 1));
11750	                    }
11751	                }
11752	                for token in CONCURRENCY_SYNC_PRIMITIVES {
11753	                    if line.contains(token) {
11754	                        scan.sync.push(format!("{relative}:{}:{token}", index + 1));
11755	                    }
11756	                }
11757	            }
11758	        }
11759	    }
11760	    Ok(scan)
11761	}
