 1270	fn verify_generated_rows(
 1271	    root: &Utf8Path,
 1272	    declared: &[Generated],
 1273	    recorded: &[GeneratedEvidence],
 1274	) -> Result<()> {
 1275	    let mut by_family = BTreeMap::new();
 1276	    for row in recorded {
 1277	        if by_family.insert(row.family.as_str(), row).is_some() {
 1278	            anyhow::bail!("generated evidence repeats family {:?}", row.family);
 1279	        }
 1280	    }
 1281	    for family in declared {
 1282	        if family.result != "pass" {
 1283	            continue;
 1284	        }
 1285	        let evidence = by_family.get(family.family.as_str()).with_context(|| {
 1286	            format!(
 1287	                "{} claims pass but the committed generated evidence has no such family",
 1288	                family.family
 1289	            )
 1290	        })?;
 1291	        // The hash covers the family's whole accept/discard stream and cannot
 1292	        // be recomputed here without rerunning 100,000 cases. It is bound
 1293	        // instead to the digest the RUN recorded, which is the strongest check
 1294	        // available at verification time: the packet may no longer cite a
 1295	        // number no run produced. Determinism of that digest is pinned
 1296	        // separately by `generated_evidence_is_byte_identical_across_runs`, so
 1297	        // editing the committed artifact to match a doctored packet is
 1298	        // detectable by rerunning the generator.
 1299	        let claimed = family
 1300	            .evidence_hash
 1301	            .as_deref()
 1302	            .context("inventory layer requires a hash before `pass`")?;
 1303	        if !claimed.eq_ignore_ascii_case(&evidence.evidence_hash) {
 1304	            anyhow::bail!(
 1305	                "{}: packet claims evidence hash {claimed} but the committed run recorded {}",
 1306	                family.family,
 1307	                evidence.evidence_hash
 1308	            );
 1309	        }
 1310	        for (label, packet_value, evidence_value) in [
 1311	            ("accepted", family.accepted, evidence.accepted),
 1312	            ("attempts", family.attempts, evidence.attempts),
 1313	            ("discards", family.discards, evidence.discards),
 1314	            ("negatives", family.negatives, evidence.negatives),
 1315	        ] {
 1316	            if packet_value != evidence_value {
 1317	                anyhow::bail!(
 1318	                    "{}: packet declares {packet_value} {label} but the committed run recorded {evidence_value}",
 1319	                    family.family
 1320	                );
 1321	            }
 1322	        }
 1323	        if family.seed != Some(evidence.seed) {
 1324	            anyhow::bail!(
 1325	                "{}: packet declares seed {:?} but the committed run used {}",
 1326	                family.family,
 1327	                family.seed,
 1328	                evidence.seed
 1329	            );
 1330	        }
 1331	        verify_generated_contract(root, family, evidence)?;
 1332	    }
 1333	    Ok(())
 1334	}
