 2961	/// The commands a resolution receipt may claim, and the gate RUNS the one it
 2962	/// claims (A09/A10 at 9eca4f0).
 2963	///
 2964	/// Before this, a receipt naming any command with a self-authored
 2965	/// `verification_exit_code: 0` was accepted without the command ever being
 2966	/// executed — the resolution asserted its own success. The command is drawn
 2967	/// from a closed registry rather than run as written: executing arbitrary text
 2968	/// out of an evidence file would hand whoever wrote the file this process.
 2969	const RESOLUTION_COMMANDS: [(&str, &[&str]); 4] = [
 2970	    ("just ci", &["just", "ci"]),
 2971	    ("just haq-inventory", &["just", "haq-inventory"]),
 2972	    ("just haq-canaries", &["just", "haq-canaries"]),
 2973	    (
 2974	        "cargo nextest run --workspace --all-features",
 2975	        &["cargo", "nextest", "run", "--workspace", "--all-features"],
 2976	    ),
 2977	];
 2978	
 2979	/// The registry's commands are the project's own gates, run with the gate's
 2980	/// environment and no timeout: they are what CI runs, so a hang here is a hang
 2981	/// in CI, visible either way (review of `e490671`). The working directory is a
 2982	/// disposable worktree at the commit the receipt names, never the live tree.
 2983	fn verify_resolution_command_ran(
 2984	    root: &Utf8Path,
 2985	    who: &str,
 2986	    evidence_text: &str,
 2987	    commit: &str,
 2988	) -> Result<()> {
 2989	    let claimed = evidence_text
 2990	        .lines()
 2991	        .find_map(|line| line.trim_start().strip_prefix("verification_command:"))
 2992	        .map(str::trim)
 2993	        .unwrap_or_default();
 2994	    let argv = RESOLUTION_COMMANDS
 2995	        .iter()
 2996	        .find(|(name, _)| *name == claimed)
 2997	        .map(|(_, argv)| *argv)
 2998	        .with_context(|| {
 2999	            format!(
 3000	                "{who}: resolution claims verification command {claimed:?}, which is not one the \
 3001	                 gate can run; the registry is closed so a receipt cannot name a command that \
 3002	                 exists only in its own text"
 3003	            )
 3004	        })?;
 3005	    let (program, rest) = argv.split_first().context("registry command is empty")?;
 3006	    // Blind pass 1 at aecb2ec7 (A12): the command ran against the working
 3007	    // tree, so a receipt claiming a finding was resolved at some commit was
 3008	    // answered by whether the command passes at HEAD. Reachability was
 3009	    // checked and the commit then ignored. It runs in a disposable worktree
 3010	    // checked out at the claimed commit now, which is what the receipt says.
 3011	    let scratch = liminal_scratch::ScratchDir::new("haq-resolution-replay")?;
 3012	    let worktree = scratch.path().to_owned();
 3013	    let add = Command::new("git")
 3014	        .current_dir(root)
 3015	        .args(["worktree", "add", "--detach", "--quiet"])
 3016	        .arg(&worktree)
 3017	        .arg(commit)
 3018	        .output()?;
 3019	    anyhow::ensure!(
 3020	        add.status.success(),
 3021	        "{who}: resolution replay worktree add at {commit} failed: {}",
 3022	        String::from_utf8_lossy(&add.stderr).trim()
 3023	    );
 3024	    let mut guard = WorktreeGuard::new(root, &worktree);
 3025	    let status = Command::new(program)
 3026	        .current_dir(&worktree)
 3027	        .args(rest)
 3028	        .status()
 3029	        .with_context(|| format!("{who}: run resolution verification {claimed:?} at {commit}"))?;
 3030	    guard.remove()?;
 3031	    anyhow::ensure!(
 3032	        status.success(),
 3033	        "{who}: resolution claims {claimed:?} exited zero at {commit}; it exited {status}"
 3034	    );
 3035	    Ok(())
 3036	}
