 8554	/// Evidence kinds every applicable critical requirement must carry
 8555	/// (ADR-0020 §2: "positive, negative, malformed/adversarial, basis/provenance,
 8556	/// and deterministic-replay evidence").
 8557	const CORE_EVIDENCE: [&str; 5] = ["positive", "negative", "malformed", "basis", "replay"];
 8558	/// "Stateful laws also have injected-fault and idempotent-recovery evidence."
 8559	const STATEFUL_EVIDENCE: [&str; 2] = ["fault", "recovery"];
 8560	/// Requirement kinds are closed by the HAQP packet contract. An open kind
 8561	/// vocabulary lets a packet relabel a stateful requirement and evade its
 8562	/// fault/recovery evidence obligations (M17.5 P1-A04).
 8563	const REQUIREMENT_KINDS: [&str; 4] = ["law", "gate", "fault", "abuse"];
 8564	/// Current packet's stateful law is M20 D20.3. Keep the semantic coordinate
 8565	/// closed even if an attacker relabels its `kind` or drops its JSON marker.
 8566	const STATEFUL_REQUIREMENT_IDS: [&str; 1] = ["P1-R015"];
 8567	/// No single test may carry more than this share of the mutation denominator.
 8568	const MAX_KILL_SHARE: f64 = 0.25;
