 8570	/// M17.5 F-05: a requirement mapped to one coarse end-to-end test is not
 8571	/// covered. Every critical requirement must carry all five core evidence
 8572	/// kinds, and fault-class requirements must additionally carry injected-fault
 8573	/// and idempotent-recovery evidence.
 8574	fn verify_evidence_coverage(packet: &Packet) -> Result<()> {
 8575	    let known = CORE_EVIDENCE
 8576	        .iter()
 8577	        .chain(STATEFUL_EVIDENCE.iter())
 8578	        .copied()
 8579	        .collect::<BTreeSet<_>>();
 8580	    let mut covered = BTreeMap::<&str, BTreeSet<&str>>::new();
 8581	    for test in &packet.tests {
 8582	        if test.evidence.is_empty() {
 8583	            anyhow::bail!("{} declares no evidence kind", test.id);
 8584	        }
 8585	        for kind in &test.evidence {
 8586	            if !known.contains(kind.as_str()) {
 8587	                anyhow::bail!("{} declares unknown evidence kind {kind}", test.id);
 8588	            }
 8589	        }
 8590	        for requirement in &test.requirements {
 8591	            covered
 8592	                .entry(requirement.as_str())
 8593	                .or_default()
 8594	                .extend(test.evidence.iter().map(String::as_str));
 8595	        }
 8596	    }
 8597	    for requirement in &packet.requirements {
 8598	        if !requirement.critical {
 8599	            continue;
 8600	        }
 8601	        let have = covered
 8602	            .get(requirement.id.as_str())
 8603	            .cloned()
 8604	            .unwrap_or_default();
 8605	        let mut needed = CORE_EVIDENCE.to_vec();
 8606	        if requirement.stateful || requirement.kind == "fault" {
 8607	            needed.extend_from_slice(&STATEFUL_EVIDENCE);
 8608	        }
 8609	        let missing = needed
 8610	            .into_iter()
 8611	            .filter(|kind| !have.contains(kind))
 8612	            .collect::<Vec<_>>();
 8613	        if !missing.is_empty() {
 8614	            anyhow::bail!(
 8615	                "critical requirement {} ({}) is missing {} evidence",
 8616	                requirement.id,
 8617	                requirement.kind,
 8618	                missing.join(", ")
 8619	            );
 8620	        }
 8621	    }
