 8676	    let test_ids = packet
 8677	        .tests
 8678	        .iter()
 8679	        .map(|row| row.id.as_str())
 8680	        .collect::<BTreeSet<_>>();
 8681	    let mut kills = BTreeMap::<&str, usize>::new();
 8682	    for mutant in &packet.mutants {
 8683	        for test in &mutant.killing_tests {
 8684	            if !test_ids.contains(test.as_str()) {
 8685	                anyhow::bail!("{} names unknown killing test {test}", mutant.id);
 8686	            }
 8687	            *kills.entry(test.as_str()).or_default() += 1;
 8688	        }
 8689	    }
 8690	    for (test, count) in &kills {
 8691	        #[allow(clippy::cast_precision_loss, reason = "inventory-scale counts")]
 8692	        let share = *count as f64 / total as f64;
 8693	        // M17.5 F-30: `>` -> `>=` survives here and is EQUIVALENT within the
 8694	        // reachable domain. `share` is `count / total` over 65 declared
 8695	        // mutants, and 65/4 is not an integer, so `share == 0.25` exactly
 8696	        // cannot occur.
 8697	        if share > MAX_KILL_SHARE {
