11622	// whatever path prefix reaches them; `.spawn(` also catches a builder. The
11623	// product crates spawn no processes today, so the over-match is a refusal
11624	// that names its line, never a miss.
11625	const CONCURRENCY_EXECUTION_PRIMITIVES: [&str; 12] = [
11626	    // Blind pass 1 at 5fb1b57 (A06): the list was Rust-shaped, so a thread
11627	    // created through libc named nothing.
11628	    "pthread_create",
11629	    "libc::clone",
11630	    "clone3",
11631	    // Blind pass 1 at aa00d41 (A06): the trailing parenthesis meant
11632	    // `let f = thread::spawn;` named no token while spawning all the same.
11633	    // A mention of the symbol is the signal; calling it is not required.
11634	    "::spawn",
11635	    ".spawn",
11636	    "::scope",
11637	    "thread::Builder",
11638	    "tokio::",
11639	    "rayon::",
11640	    "async fn",
11641	    "crossbeam",
11642	    "mpsc::",
11643	];
11644	/// Tokens that mean code is written to be shared: recorded, not refused.
11645	const CONCURRENCY_SYNC_PRIMITIVES: [&str; 3] = ["Mutex<", "RwLock<", "Atomic"];
