 11736	                    }
 11737	                    continue;
 11738	                }
 11739	                if trimmed.replace(' ', "") == "#[cfg(test)]" {
 11740	                    skipping = Some((0, false));
 11741	                    continue;
 11742	                }
 11743	                if trimmed.starts_with("//") {
