2599	/// One review row against its own committed record (M17.5 F-27 / P1-A05, A06).
2600	///
2601	/// The previous version counted the record's `attempts` array and stopped, so a
2602	/// record of twelve EMPTY objects satisfied it, and a record whose own `result`
2603	/// was `fail` satisfied a packet row claiming `pass`. Everything a reviewer
2604	/// actually concluded was unread.
2605	#[allow(
2606	    clippy::too_many_lines,
2607	    reason = "one review record's contract is one contract; splitting it by line count would scatter the checks a reader must see together"
2608	)]
2609	/// The reviewer's raw answer lives beside its record as `<record>.raw.txt`;
2610	/// its SHA-256 must be the record's `raw_response_sha256` (A09).
2611	fn verify_review_raw_response(
2612	    root: &Utf8Path,
2613	    record_path: &Utf8Path,
2614	    expected: &str,
2615	) -> Result<()> {
2616	    let raw_path = record_path.with_extension("raw.txt");
2617	    let relative = raw_path.strip_prefix(root).unwrap_or(&raw_path);
2618	    let raw = fs::read(&raw_path).with_context(|| {
2619	        format!("{relative}: the reviewer's raw answer must be retained beside its record")
2620	    })?;
2621	    let actual = format!("{:x}", Sha256::digest(&raw));
2622	    require_eq(
2623	        "review raw_response_sha256 (of the retained answer)",
2624	        &actual,
2625	        expected,
2626	    )
2627	}
