2559	fn verify_cross_pass_reproduction(records: &[(String, ReviewRecord)]) -> Result<()> {
2560	    if records.is_empty() {
2561	        return Ok(());
2562	    }
2563	    anyhow::ensure!(
2564	        records.len() == 2,
2565	        "cross-pass reproduction requires two records"
2566	    );
2567	    for (index, (who, record)) in records.iter().enumerate() {
2568	        let other = &records[1 - index].1;
2569	        let findings = review_finding_ids(&record.findings, &record.attempts, who)?;
2570	        for finding_id in &record.independently_reproduced {
2571	            let attempt_id = findings.get(finding_id.as_str()).with_context(|| {
2572	                format!("{who}: reproduced finding {finding_id:?} is not linked")
2573	            })?;
2574	            let attempt = record
2575	                .attempts
2576	                .iter()
2577	                .find(|attempt| attempt.id == *attempt_id)
2578	                .expect("finding linkage validated");
2579	            let matches = other
2580	                .attempts
2581	                .iter()
2582	                .filter(|candidate| {
2583	                    candidate.classification == "verified_defect"
2584	                        && candidate.independently_reproduced
2585	                        && candidate.attack_class == attempt.attack_class
2586	                        && candidate.target == attempt.target
2587	                        && reports_the_same_defect(candidate, attempt)
2588	                })
2589	                .count();
2590	            anyhow::ensure!(
2591	                matches == 1,
2592	                "{who}: reproduced finding {finding_id:?} needs exactly one independently reproduced defect in the other pass with the same attack class, the same source coordinate, and a report about the same defect; found {matches}"
2593	            );
2594	        }
2595	    }
2596	    Ok(())
2597	}
