14000	///
14001	/// The timings are returned SEPARATELY rather than embedded in the rows on
14002	/// purpose: the rows are the hashable artifact and must be a pure function of
14003	/// the seed and the code under test, while the timings are telemetry for the
14004	/// operator (M17.5 pass-2 #18).
14005	///
14006	/// The case-count guard is a separate function so its BOUNDARIES are testable:
14007	/// `>` -> `>=` at the safety limit can only be discriminated by a case that
14008	/// runs at exactly 10,000,000, which no test can afford. Extracting the
14009	/// predicate makes the boundary checkable in microseconds (M17.5 F-30).
14010	/// Reject a case count that is zero or beyond the safety limit.
14011	fn validate_case_count(cases: u64) -> Result<()> {
14012	    if cases == 0 {
14013	        anyhow::bail!("generated case count must be positive");
14014	    }
14015	    if cases > 10_000_000 {
14016	        anyhow::bail!("generated case count exceeds safety limit: {cases} > 10000000");
14017	    }
14018	    Ok(())
14019	}
