12911	/// Run deterministic generated checks for all five HAQP families. This records
12912	/// generated-case evidence only; sanitizer wall-clock qualification remains a
12913	/// separate `cargo fuzz` lane and is never inferred from this command.
12914	/// Deterministic 64-bit stream; one seed per case, recorded per family.
12915	struct Rng(u64);
12916	impl Rng {
12917	    fn next(&mut self) -> u64 {
12918	        self.0 = self
12919	            .0
12920	            .wrapping_mul(6_364_136_223_846_793_005)
12921	            .wrapping_add(1_442_695_040_888_963_407);
12922	        self.0 ^ (self.0 >> 31)
12923	    }
12924	    fn below(&mut self, n: u64) -> u64 {
12925	        self.next() % n.max(1)
12926	    }
12927	    /// A deterministic identifier drawn from the seeded stream.
12928	    ///
12929	    /// M17.5 F-16: the generators minted ids with `NodeId::new()`,
12930	    /// `RepairStepId::new()` and friends, all of which are `Uuid::now_v7()` —
12931	    /// wall-clock milliseconds plus OS randomness. So the `seed` recorded in the
12932	    /// packet, whose stated purpose is to make the campaign reproducible under
12933	    /// ADR-0020 §1, did not reproduce a run: a crash at case 45,231 could not be
12934	    /// replayed from it. The defect stayed invisible because the digest absorbed
12935	    /// only RNG state, so nothing the ids touched ever reached the artifact.
12936	    ///
12937	    /// v5 (namespaced SHA-1 of the seeded bytes) rather than v7, because a
12938	    /// deterministic v7 would have to invent a timestamp. The ids are opaque to
12939	    /// every assertion here; nothing in these families depends on UUID version
12940	    /// or on time ordering. That is a mild strengthening: v7 ids arrive in
12941	    /// ascending creation order, so `topo_order` was only ever exercised on
12942	    /// plans whose id order agreed with insertion order.
12943	    fn uuid(&mut self) -> uuid::Uuid {
12944	        let mut bytes = [0_u8; 16];
12945	        bytes[..8].copy_from_slice(&self.next().to_le_bytes());
12946	        bytes[8..].copy_from_slice(&self.next().to_le_bytes());
12947	        uuid::Uuid::new_v5(&uuid::Uuid::NAMESPACE_OID, &bytes)
12948	    }
12949	    fn word(&mut self) -> String {
12950	        const ALPHABET: &[u8] = b"abcdefghijklmnopqrstuvwxyz0123456789-_ ";
12951	        let len = 1 + self.below(12);
12952	        (0..len)
12953	            .map(|_| {
12954	                let idx = usize::try_from(self.below(ALPHABET.len() as u64)).expect("index fits");
12955	                char::from(ALPHABET[idx])
12956	            })
12957	            .collect()
12958	    }
12959	
12960	    fn category(&mut self, family: &str) -> &'static str {
12961	        let categories = generated_seed_categories(family);
12962	        let index = usize::try_from(self.below(categories.len() as u64)).expect("category index");
12963	        categories[index]
12964	    }
12965	}
