 14025	fn generate_evidence(cases: u64) -> Result<(Vec<GeneratedEvidence>, Vec<u64>)> {
 14026	    validate_case_count(cases)?;
 14027	    let families: [Family; 5] = [
 14028	        ("source/CST/formatting", case_source_cst),
 14029	        ("graph/interchange codecs", case_interchange),
 14030	        ("transforms/projections", case_transform),
 14031	        ("repair/ILRP/recovery", case_repair),
 14032	        ("Basis/revision/query invalidation", case_invalidation),
 14033	    ];
 14034	
 14035	    let mut evidence = Vec::new();
 14036	    let mut timings = Vec::new();
 14037	    for (index, (family, run)) in families.into_iter().enumerate() {
 14038	        let seed = 0x9E37_79B9_7F4A_7C15_u64 ^ (index as u64).wrapping_mul(0x0100_0000_01B3);
 14039	        let mut rng = Rng(seed);
 14040	        let started = Instant::now();
 14041	        let mut digest = blake3::Hasher::new();
 14042	        digest.update(&seed.to_le_bytes());
 14043	        // ADR-0020 §4 requires >=100,000 ACCEPTED cases, so run until the
 14044	        // acceptance target is met rather than stopping at N attempts. The
 14045	        // attempt cap keeps a badly-targeted generator from running forever
 14046	        // instead of silently reporting a short campaign.
 14047	        let (mut accepted, mut discards, mut negatives, mut attempts) = (0u64, 0u64, 0u64, 0u64);
 14048	        let mut category_counts = BTreeMap::<String, u64>::new();
 14049	        // Negative categories are exercised inputs, not discards; families
 14050	        // with broad malformed coverage need a larger attempt budget to reach
 14051	        // their accepted floor without silently dropping categories.
 14052	        let attempt_cap = cases.saturating_mul(4);
 14053	        while accepted < cases {
 14054	            anyhow::ensure!(
 14055	                attempts < attempt_cap,
 14056	                "{family}: {attempts} attempts yielded only {accepted}/{cases} accepted \
 14057	                 — the generator is not targeting its declared domain"
 14058	            );
 14059	            attempts += 1;
 14060	            match run(&mut rng).with_context(|| format!("{family} attempt {attempts}"))? {
 14061	                Case::Accepted { category, witness } => {
 14062	                    // A family that witnesses nothing would restore exactly the
 14063	                    // #16 defect: a digest independent of the code under test.
 14064	                    anyhow::ensure!(
 14065	                        !witness.is_empty(),
 14066	                        "{family}: accepted attempt {attempts} with an empty witness, so \
 14067	                         the evidence hash would not depend on what the code produced"
 14068	                    );
 14069	                    accepted += 1;
 14070	                    *category_counts.entry(category.to_owned()).or_default() += 1;
 14071	                    digest.update(b"A");
 14072	                    digest.update(category.as_bytes());
 14073	                    digest.update(&witness);
 14074	                }
 14075	                Case::Discarded { category, witness } => {
 14076	                    anyhow::ensure!(
 14077	                        !witness.is_empty(),
 14078	                        "{family}: discarded attempt {attempts} with an empty witness, so \
 14079	                         the evidence records that something was discarded and not what"
 14080	                    );
 14081	                    discards += 1;
 14082	                    *category_counts.entry(category.to_owned()).or_default() += 1;
 14083	                    digest.update(b"D");
 14084	                    digest.update(category.as_bytes());
 14085	                    digest.update(&witness);
 14086	                }
 14087	                Case::Negative { category, witness } => {
 14088	                    anyhow::ensure!(
 14089	                        !witness.is_empty(),
 14090	                        "{family}: negative attempt {attempts} has an empty witness"
 14091	                    );
 14092	                    negatives += 1;
 14093	                    *category_counts.entry(category.to_owned()).or_default() += 1;
 14094	                    digest.update(b"N");
 14095	                    digest.update(category.as_bytes());
 14096	                    digest.update(&witness);
 14097	                }
 14098	            }
 14099	            // The RNG state binds the INPUT; the witness above binds the OUTPUT.
 14100	            digest.update(&rng.0.to_le_bytes());
 14101	        }
 14102	        anyhow::ensure!(
 14103	            accepted + discards + negatives == attempts,
 14104	            "{family}: accounting lost cases"
 14105	        );
 14106	        let evidence_hash = digest.finalize().to_hex().to_string();
 14107	        let relation_rows = generated_relations(family)
 14108	            .iter()
 14109	            .map(|relation| GeneratedRelationEvidence {
 14110	                relation: (*relation).to_owned(),
 14111	                oracle_id: format!("oracle:{}", family.replace(['/', ' ', '-'], "_")),
 14112	                result: "pass".to_owned(),
 14113	                artifact_blake3: blake3::hash(
 14114	                    format!("{family}\0{relation}\0{evidence_hash}").as_bytes(),
 14115	                )
 14116	                .to_hex()
 14117	                .to_string(),
 14118	            })
 14119	            .collect::<Vec<_>>();
 14120	        let relation_matrix_blake3 = blake3::hash(
 14121	            serde_json::to_vec(&relation_rows)
 14122	                .context("serialize generated relation matrix")?
 14123	                .as_slice(),
 14124	        )
 14125	        .to_hex()
 14126	        .to_string();
 14127	        evidence.push(GeneratedEvidence {
 14128	            family: family.to_owned(),
 14129	            accepted,
 14130	            attempts,
 14131	            discards,
 14132	            negatives,
 14133	            seed,
 14134	            evidence_hash,
 14135	            category_counts,
 14136	            relations: relation_rows,
 14137	            oracle: Some(GeneratedOracleEvidence {
 14138	                id: format!("oracle:{}", family.replace(['/', ' ', '-'], "_")),
 14139	                source: generated_oracle_source(family).to_owned(),
 14140	                independent: true,
 14141	                relation_matrix_blake3,
 14142	            }),
 14143	        });
 14144	        timings.push(u64::try_from(started.elapsed().as_millis()).unwrap_or(u64::MAX));
 14145	    }
 14146	    Ok((evidence, timings))
 14147	}
