 3927	/// The killing tests AM-17.10 derives for `mutant`: the candidates are the
 3928	/// tests the packet maps to its requirement, in packet order; the primary is
 3929	/// the first candidate observed the way this operator shows itself; the
 3930	/// secondary is the first remaining candidate of a different evidence kind.
 3931	/// Each fallback is to the next candidate, never outside the requirement.
 3932	fn derive_killing_tests(packet: &Packet, mutant: &Mutant) -> Result<Vec<String>> {
 3933	    // Position among the mutants sharing this requirement. F-05 caps any one
 3934	    // test at a quarter of the plan, and a rule that always picked the first
 3935	    // apt candidate put P1-T07 on 46% of it. Rotation spreads the claim across
 3936	    // the tests that defend the requirement instead of piling it on the first.
 3937	    let ordinal = packet
 3938	        .mutants
 3939	        .iter()
 3940	        .take_while(|other| other.id != mutant.id)
 3941	        .filter(|other| other.requirement == mutant.requirement)
 3942	        .count();
 3943	    let observed = MUTANT_OBSERVATION_KIND
 3944	        .iter()
 3945	        .find(|(operator, _)| *operator == mutant.operator)
 3946	        .map(|(_, kind)| *kind)
 3947	        .with_context(|| {
 3948	            format!(
 3949	                "{} carries operator {:?}, which names no observation kind; AM-17.10 requires \
 3950	                 one before the plan can carry the operator",
 3951	                mutant.id, mutant.operator
 3952	            )
 3953	        })?;
 3954	    let candidates: Vec<&Test> = packet
 3955	        .tests
 3956	        .iter()
 3957	        .filter(|test| test.requirements.contains(&mutant.requirement))
 3958	        .collect();
 3959	    anyhow::ensure!(
 3960	        candidates.len() >= 2,
 3961	        "{} names requirement {}, which {} test(s) defend; a pair of killers needs two",
 3962	        mutant.id,
 3963	        mutant.requirement,
 3964	        candidates.len()
 3965	    );
 3966	    let observed_candidates: Vec<&&Test> = candidates
 3967	        .iter()
 3968	        .filter(|test| test.evidence.iter().any(|kind| kind == observed))
 3969	        .collect();
 3970	    // Rotation applies whether or not the operator's kind is available: the
 3971	    // fallback candidate list is still a list, and taking its head every time
 3972	    // is what put one test on 46% of the plan (review of `95a97b8b`).
 3973	    let primary = if observed_candidates.is_empty() {
 3974	        candidates[ordinal % candidates.len()]
 3975	    } else {
 3976	        observed_candidates[ordinal % observed_candidates.len()]
 3977	    };
 3978	    let start = candidates
 3979	        .iter()
 3980	        .position(|test| test.id == primary.id)
 3981	        .context("the primary is one of the candidates")?;
 3982	    let after = |step: usize| candidates[(start + step) % candidates.len()];
 3983	    let secondary = (1..candidates.len())
 3984	        .map(after)
 3985	        .find(|test| test.evidence != primary.evidence)
 3986	        .unwrap_or_else(|| after(1));
 3987	    Ok(vec![primary.id.clone(), secondary.id.clone()])
 3988	}
