 4007	fn verify_mutant_killing_tests(root: &Utf8Path, packet: &Packet) -> Result<()> {
 4008	    // AM-17.10: the column is derived for every mutant, whatever its
 4009	    // disposition, and is checked before the clauses that inspect only killed
 4010	    // ones. This function used to return here when nothing was killed, so at
 4011	    // stage 1a — where all 65 mutants are predeclared — it read nothing at
 4012	    // all, and a generated killer column rode through fourteen lanes.
 4013	    let killed: Vec<&Mutant> = packet
 4014	        .mutants
 4015	        .iter()
 4016	        .filter(|mutant| mutant.disposition == "killed")
 4017	        .collect();
 4018	    let by_id: BTreeMap<&str, &Test> = packet
 4019	        .tests
 4020	        .iter()
 4021	        .map(|test| (test.id.as_str(), test))
 4022	        .collect();
 4023	    let ignored = ignored_test_names(root);
 4024	    for mutant in killed {
 4025	        if mutant.killing_tests.is_empty() {
 4026	            anyhow::bail!("{} claims killed but names no killing test", mutant.id);
 4027	        }
 4028	        for test_id in &mutant.killing_tests {
 4029	            let test = by_id.get(test_id.as_str()).with_context(|| {
 4030	                format!(
 4031	                    "{} names killing test {test_id}, which the packet does not declare",
 4032	                    mutant.id
 4033	                )
 4034	            })?;
 4035	            let leaf = test.name.rsplit("::").next().unwrap_or(test.name.as_str());
 4036	            if ignored.contains(leaf) {
 4037	                anyhow::bail!(
 4038	                    "{} claims killed by {} ({}), which is #[ignore]d — an ignored test \
 4039	                     never runs, so it cannot witness a kill",
 4040	                    mutant.id,
 4041	                    test_id,
 4042	                    test.name
 4043	                );
 4044	            }
 4045	        }
 4046	    }
 4047	    // AM-17.10: every mutant's column is derived, whatever its disposition.
 4048	    // Checked last so a kill witnessed by an ignored or missing test reports
 4049	    // that, rather than being answered by the derivation. The clauses above
 4050	    // inspect only `killed` mutants, which is why a plan of 65 predeclared
 4051	    // mutants carried a generated killer column through fourteen lanes with
 4052	    // no gate reading it at all.
 4053	    for mutant in &packet.mutants {
 4054	        let derived = derive_killing_tests(packet, mutant)?;
 4055	        anyhow::ensure!(
 4056	            mutant.killing_tests == derived,
 4057	            "{} names killing tests {:?}; AM-17.10 derives {:?} from requirement {} and \
 4058	             operator {:?}",
 4059	            mutant.id,
 4060	            mutant.killing_tests,
 4061	            derived,
 4062	            mutant.requirement,
 4063	            mutant.operator
 4064	        );
 4065	    }
 4066	    Ok(())
 4067	}
