 9141	fn anchor_is_mutable_line(line: &str) -> bool {
 9142	    let trimmed = line.trim();
 9143	    let declares_item = [
 9144	        "fn ",
 9145	        "pub fn ",
 9146	        "pub(crate) fn ",
 9147	        "async fn ",
 9148	        "pub async fn ",
 9149	        "struct ",
 9150	        "pub struct ",
 9151	        "enum ",
 9152	        "pub enum ",
 9153	        "trait ",
 9154	        "pub trait ",
 9155	        "impl ",
 9156	        // Blind pass 1 at 9eca4f0 (A05): `impl<C: CrashInjector> CrashInjector
 9157	        // for &C {` starts with `impl<`, not `impl `, so a generic impl header
 9158	        // read as behaviour.
 9159	        "impl<",
 9160	        "mod ",
 9161	        "pub mod ",
 9162	        "type ",
 9163	        "pub type ",
 9164	        "use ",
 9165	        "pub use ",
 9166	        "pub(crate) use ",
 9167	        // Blind pass 1 at aa00d41 (A04): P1-M046 was anchored on
 9168	        // `pub const REPAIR_STALE_BASIS: &str = "JUR053";`. Deleting a
 9169	        // diagnostic code's name changes compilation, not staleness semantics.
 9170	        // A const is not always inert, though — see `binds_a_threshold`.
 9171	        "const ",
 9172	        "pub const ",
 9173	        "pub(crate) const ",
 9174	        "static ",
 9175	        "pub static ",
 9176	    ]
 9177	    .iter()
 9178	    .any(|kw| trimmed.starts_with(kw));
 9179	    // A bare `Variant {` / `Variant,` inside an enum body.
 9180	    let declares_variant = trimmed.chars().next().is_some_and(char::is_uppercase)
 9181	        && (trimmed.ends_with('{') || trimmed.ends_with(','))
 9182	        && !trimmed.contains('=')
 9183	        && !trimmed.contains('(');
 9184	    // A constant that binds a NUMBER is the canonical threshold site:
 9185	    // `pub const MAX_NESTING: u16 = 256;` is exactly what threshold ±1 moves,
 9186	    // and refusing it would push the plan off the very lines §3 asks for. A
 9187	    // constant binding a string, or an array whose length is the only number,
 9188	    // stays a declaration: 256 can become 257, `[IntentState; 7]` cannot
 9189	    // become 8 and still compile.
 9190	    let binds_a_threshold = declares_item
 9191	        && trimmed.contains("const ")
 9192	        && trimmed.split_once('=').is_some_and(|(_, value)| {
 9193	            // The VALUE must be a number, not merely contain a digit:
 9194	            // `pub const TAG: &str = "v2";` is still a declaration (review of
 9195	            // c455cdf). A newtype around a number counts: `RelationFlags(1)`.
 9196	            let value = value.trim().trim_end_matches(';').trim();
 9197	            let inner = value
 9198	                .split_once('(')
 9199	                .map_or(value, |(_, rest)| rest.trim_end_matches(')'));
 9200	            // Strip a trailing type suffix (`256u16`) before asking whether
 9201	            // what remains is a number.
 9202	            !value.starts_with('"')
 9203	                && !inner.is_empty()
 9204	                && inner
 9205	                    .trim_end_matches(|ch: char| ch.is_ascii_alphabetic() || ch == '_')
 9206	                    .chars()
 9207	                    .all(|ch| ch.is_ascii_digit() || ch == '_')
 9208	        });
 9209	    // Blind pass 1 at 9eca4f0 (A11): a multi-line signature's continuation —
 9210	    // `) -> Result<WorkspaceBasis, PerspectiveError> {` — begins with none of
 9211	    // the keywords above and so read as behaviour. A line that closes a
 9212	    // parameter list and opens a body is still a declaration.
 9213	    // `) -> Result<..> {` and `) {` continue a signature. A bare `);` does NOT:
 9214	    // it terminates any multi-line call, which is behaviour, and refusing it
 9215	    // would push legitimate anchors off real code (review of `e490671`).
 9216	    let continues_signature =
 9217	        trimmed.starts_with(')') && (trimmed.contains("->") || trimmed.ends_with('{'));
 9218	    !(declares_item || declares_variant || continues_signature) || binds_a_threshold
 9219	}
