 9337	/// The hash count and the index just past the opening quote of a raw string
 9338	/// starting at `at`, or `None` if one does not start there.
 9339	fn raw_string_opening(chars: &[char], at: usize) -> Option<(usize, usize)> {
 9340	    let mut i = at;
 9341	    if chars.get(i) == Some(&'b') {
 9342	        i += 1;
 9343	    }
 9344	    if chars.get(i) != Some(&'r') {
 9345	        return None;
 9346	    }
 9347	    i += 1;
 9348	    let hashes = chars[i..].iter().take_while(|c| **c == '#').count();
 9349	    i += hashes;
 9350	    if chars.get(i) != Some(&'"') {
 9351	        return None;
 9352	    }
 9353	    Some((hashes, i + 1))
 9354	}
 9355	
 9356	/// The index past a raw string's terminator, searching from `from`, or `None`
 9357	/// when the line ends inside it. Counted rather than `all`: on a tail shorter
 9358	/// than `hashes` an `all` is vacuously true, which would close the literal on
 9359	/// a quote that does not terminate it.
 9360	fn raw_string_close(chars: &[char], from: usize, hashes: usize) -> Option<usize> {
 9361	    let mut i = from;
 9362	    while i < chars.len() {
 9363	        if chars[i] == '"'
 9364	            && chars[i + 1..]
 9365	                .iter()
 9366	                .take(hashes)
 9367	                .filter(|c| **c == '#')
 9368	                .count()
 9369	                == hashes
 9370	        {
 9371	            return Some(i + 1 + hashes);
 9372	        }
 9373	        i += 1;
 9374	    }
 9375	    None
 9376	}
 9377	
 9378	/// The index past the string literal opening at `at`, or the end of the line.
 9379	fn skip_string(chars: &[char], at: usize) -> usize {
 9380	    let mut i = at + 1;
 9381	    while i < chars.len() {
 9382	        match chars[i] {
 9383	            '\\' => i += 2,
 9384	            '"' => return i + 1,
 9385	            _ => i += 1,
 9386	        }
 9387	    }
 9388	    chars.len()
 9389	}
 9390	
 9391	/// The index past the character literal opening at `at`, or `None` when the
 9392	/// quote introduces a lifetime rather than a literal.
 9393	fn skip_char_literal(chars: &[char], at: usize) -> Option<usize> {
 9394	    if chars.get(at) != Some(&'\'') {
 9395	        return None;
 9396	    }
 9397	    if chars.get(at + 1) == Some(&'\\') {
 9398	        // Past the backslash and the character it escapes: in `'\''` the quote
 9399	        // at `at + 2` is the escaped character, not the terminator.
 9400	        let close = chars.get(at + 3..)?.iter().position(|c| *c == '\'')?;
 9401	        return Some(at + 4 + close);
 9402	    }
 9403	    if chars.get(at + 2) == Some(&'\'') {
 9404	        return Some(at + 3);
 9405	    }
 9406	    None
 9407	}
