 9527	/// Every declared mutant's anchor line must be able to CARRY its operator
 9528	/// (M17.5 F-33). Runs at every layer, including stage 1a, because an
 9529	/// inapplicable mutant is a defect in the inventory, not in the evidence.
 9530	/// The locked corpus must be reachable by exactly one name (M17.5 F-34 /
 9531	/// blind pass 1 A07).
 9532	///
 9533	/// The corpus-access audit refuses a traced path containing `heldout` or
 9534	/// `conformance/corpora`. That is substring matching on what the process SAW,
 9535	/// so it catches direct access and nothing else: a symlink or a rename gives
 9536	/// the same bytes a path the filter does not recognise, and the audit reports
 9537	/// clean while the locked corpus was read.
 9538	///
 9539	/// Rather than try to canonicalize strace output after the fact — the symlink
 9540	/// may not exist by verification time — the aliasing itself is made
 9541	/// impossible. If the locked corpus has exactly one name, then matching that
 9542	/// name is sufficient, and the existing filter becomes sound rather than
 9543	/// lucky.
 9544	fn verify_locked_corpus_has_no_aliases(root: &Utf8Path) -> Result<()> {
 9545	    use std::os::unix::fs::MetadataExt as _;
 9546	    let locked = root.join("conformance/corpora/heldout");
 9547	    // M17.5 F-65: this returned Ok when the corpus was absent, and nothing
 9548	    // else in the gate required it to exist — so a tree with the corpus
 9549	    // deleted passed every corpus check vacuously while the packet went on
 9550	    // declaring `locked_acceptance_corpora_touched: false`. Twenty-three files
 9551	    // are tracked; absence is a broken tree, not an empty obligation.
 9552	    anyhow::ensure!(
 9553	        locked.is_dir(),
 9554	        "{locked} is missing: the locked corpus cannot be shown untouched when it is not there"
 9555	    );
 9556	    let identities = locked_corpus_identities(root, "conformance/corpora")?;
 9557	    let canonical = fs::canonicalize(&locked)
 9558	        .with_context(|| format!("{locked}: locked corpus must resolve"))?;
 9559	    let mut aliases = Vec::new();
 9560	    let mut stack = vec![root.to_owned()];
 9561	    while let Some(dir) = stack.pop() {
 9562	        // A directory this cannot read is a directory it cannot clear of
 9563	        // aliases; the same silent skip was a hard-link bypass in F-64.
 9564	        let entries = fs::read_dir(&dir)
 9565	            .with_context(|| format!("{dir}: scan the tree for corpus aliases"))?;
 9566	        for entry in entries.flatten() {
 9567	            let Ok(path) = Utf8PathBuf::from_path_buf(entry.path()) else {
 9568	                continue;
 9569	            };
 9570	            let name = path.file_name().unwrap_or_default();
 9571	            if name == ".git" || name == "target" {
 9572	                continue;
 9573	            }
 9574	            let Ok(meta) = entry.path().symlink_metadata() else {
 9575	                continue;
 9576	            };
 9577	            // Blind pass 1 at `ec045588` (A08): only symlinks counted. A hard
 9578	            // link is the alias no path reasoning sees, and one created
 9579	            // outside a traced process leaves the trace naming an innocent
 9580	            // path; if it is then removed, neither the lexical fragments nor
 9581	            // the inode check can resolve it afterwards. An alias that still
 9582	            // exists in the tree is found here, which is where it can be.
 9583	            if meta.is_file() && identities.contains(&(meta.dev(), meta.ino())) {
 9584	                // The identity set covers the whole corpora tree, so a file
 9585	                // inside it is the corpus rather than an alias to it.
 9586	                let corpora = root.join("conformance/corpora");
 9587	                let inside = Utf8PathBuf::from_path_buf(entry.path())
 9588	                    .is_ok_and(|path| path.starts_with(&corpora));
 9589	                if !inside {
 9590	                    aliases.push(entry.path().display().to_string());
 9591	                }
 9592	            }
 9593	            if meta.file_type().is_symlink() {
 9594	                // A link INTO the locked tree gives its bytes a second name.
 9595	                if let Ok(resolved) = fs::canonicalize(entry.path())
 9596	                    && (resolved == canonical || resolved.starts_with(&canonical))
 9597	                    && path != locked
 9598	                {
 9599	                    aliases.push(path.to_string());
 9600	                }
 9601	            } else if meta.is_dir() {
 9602	                stack.push(path);
 9603	            }
 9604	        }
 9605	    }
 9606	    anyhow::ensure!(
 9607	        aliases.is_empty(),
 9608	        "the locked acceptance corpus is reachable under {} alias(es), so a traced \
 9609	         path can read it without naming it: {aliases:?}",
 9610	        aliases.len()
 9611	    );
 9612	    Ok(())
 9613	}
