 2045	/// Independent invalidation oracle. It compares expected read membership to
 2046	/// observed invalidation answers, including a negative witness.
 2047	fn independent_oracle_source_invalidation(
 2048	    deps: &mut liminal_revision::ComponentDeps,
 2049	    expected: &BTreeSet<liminal_id::JurisdictionKey>,
 2050	    unrelated: &liminal_id::JurisdictionKey,
 2051	    extra: &liminal_id::JurisdictionKey,
 2052	) -> Result<Vec<u8>> {
 2053	    for key in expected {
 2054	        anyhow::ensure!(
 2055	            deps.invalidated_by(key),
 2056	            "a recorded read did not invalidate: {key:?}"
 2057	        );
 2058	    }
 2059	    anyhow::ensure!(
 2060	        !deps.invalidated_by(unrelated),
 2061	        "an unread key invalidated the computation: {unrelated:?}"
 2062	    );
 2063	    // Add a new dependency only between observations. This makes the second
 2064	    // check a real monotonicity assertion instead of repeating the first one.
 2065	    anyhow::ensure!(
 2066	        !deps.invalidated_by(extra),
 2067	        "extra dependency was already present before monotonicity probe: {extra:?}"
 2068	    );
 2069	    deps.record(extra.clone());
 2070	    // Blind pass 1 at aa00d41 (A03): the relation only re-checked the keys that
 2071	    // already invalidated, so a `record` that did nothing passed. Monotonicity
 2072	    // is that the new read is now observed AND no old one was lost.
 2073	    anyhow::ensure!(
 2074	        deps.invalidated_by(extra),
 2075	        "recording a read did not make it invalidate: {extra:?}"
 2076	    );
 2077	    for key in expected {
 2078	        anyhow::ensure!(
 2079	            deps.invalidated_by(key),
 2080	            "recording another read un-invalidated {key:?}"
 2081	        );
 2082	    }
 2083	    anyhow::ensure!(
 2084	        !deps.invalidated_by(unrelated),
 2085	        "recording a read invalidated an unread key: {unrelated:?}"
 2086	    );
 2087	    let mut witness = Vec::new();
 2088	    for key in expected.iter().chain([unrelated, extra]) {
 2089	        witness.push(u8::from(deps.invalidated_by(key)));
 2090	    }
 2091	    Ok(witness)
 2092	}
