 9011	/// ADR-0020 §3's shape rules for the plan: thirteen mutants per family, no
 9012	/// operator over a quarter of the denominator, and every named operator
 9013	/// present (blind pass 1 at 5fb1b57, A04).
 9014	fn verify_mutation_plan_balance(
 9015	    by_family: &BTreeMap<&str, usize>,
 9016	    by_operator: &BTreeMap<&str, usize>,
 9017	) -> Result<()> {
 9018	    const REQUIRED_OPERATORS: [&str; 13] = [
 9019	        "predicate-deletion",
 9020	        "predicate-inversion",
 9021	        "threshold-plus-one",
 9022	        "threshold-minus-one",
 9023	        "missing-enum-dispatch",
 9024	        "success-error-substitution",
 9025	        "stale-basis-acceptance",
 9026	        "wrong-holder-selection",
 9027	        "skipped-durable-transition",
 9028	        "disabled-crash-point",
 9029	        "ordering-nondeterminism",
 9030	        "oracle-short-circuit",
 9031	        "broadened-allow-list",
 9032	    ];
 9033	    for (family, count) in by_family {
 9034	        if *count != 13 {
 9035	            anyhow::bail!("family {family} mutant count must be 13, got {count}");
 9036	        }
 9037	    }
 9038	    for (operator, count) in by_operator {
 9039	        if *count > 16 {
 9040	            anyhow::bail!("operator {operator} supplies {count} mutants; max 16");
 9041	        }
 9042	    }
 9043	    // Blind pass 1 at 5fb1b57 (A04): the tally only bounded operators that were
 9044	    // PRESENT, so dropping one entirely — broadened-allow-list has a single
 9045	    // mutant — left the plan short an operator ADR-0020 §3 names and nothing
 9046	    // said so. The list is the ADR's, closed.
 9047	    let missing = REQUIRED_OPERATORS
 9048	        .into_iter()
 9049	        .filter(|operator| !by_operator.contains_key(operator))
 9050	        .collect::<Vec<_>>();
 9051	    anyhow::ensure!(
 9052	        missing.is_empty(),
 9053	        "the mutation plan declares no {missing:?}; ADR-0020 §3 names every operator the plan \
 9054	         must exercise, and an absent one cannot be killed or counted"
 9055	    );
 9056	    Ok(())
 9057	}
