 9110	fn use_aliases(line: &str) -> Vec<(String, String)> {
 9111	    // Blind pass 1 at ee646f8c (A10, A11): `pub use x::y as z;` is a `use`
 9112	    // with a visibility in front, and stripping only `use ` meant the alias
 9113	    // bound nothing — in the oracle's independence scan and in the durable
 9114	    // transition census, which share this parser.
 9115	    let Some(rest) = without_visibility(line).strip_prefix("use ") else {
 9116	        return Vec::new();
 9117	    };
 9118	    // Braces are dropped rather than parsed, so a nested group
 9119	    // (`use a::{b::{c as d}};`) reads the same as a flat one: what matters is
 9120	    // the trailing `symbol as alias`, and the path before it is only used for
 9121	    // its last segment (review of d09978c).
 9122	    let flattened = rest.trim_end_matches(';').replace(['{', '}'], "");
 9123	    let items = flattened.split(',').map(str::trim).collect::<Vec<_>>();
 9124	    items
 9125	        .iter()
 9126	        .filter_map(|item| {
 9127	            let (path, alias) = item.split_once(" as ")?;
 9128	            // `rsplit` always yields at least one element.
 9129	            let symbol = path
 9130	                .rsplit("::")
 9131	                .next()
 9132	                .unwrap_or_default()
 9133	                .trim()
 9134	                .to_owned();
 9135	            let alias = alias.trim().to_owned();
 9136	            (alias != "_").then_some((symbol, alias))
 9137	        })
 9138	        .collect()
 9139	}
