 9221	/// Whether `line` in `text` falls inside a `#[cfg(test)]` item.
 9222	///
 9223	/// Blind pass 1 at 9eca4f0 (A12): P1-M053 was anchored on
 9224	/// `assert!(!deps.invalidated_by(&b));` inside `mod tests`. Deleting that
 9225	/// predicate mutates the ORACLE, so killing it measures the test's own
 9226	/// assertion rather than the product's invalidation behaviour — the shared-
 9227	/// oracle defect this campaign exists to catch, declared as a mutant.
 9228	fn line_is_inside_test_code(text: &str, line: usize) -> bool {
 9229	    let mut depth = 0i32;
 9230	    let mut in_test = false;
 9231	    let mut test_depth = 0i32;
 9232	    let mut scanner = SourceScanner::default();
 9233	    for (index, source) in text.lines().enumerate() {
 9234	        let trimmed = source.trim();
 9235	        if index + 1 == line {
 9236	            return in_test;
 9237	        }
 9238	        if !in_test && trimmed.replace(' ', "") == "#[cfg(test)]" {
 9239	            in_test = true;
 9240	            test_depth = depth;
 9241	            scanner.structural(source);
 9242	            continue;
 9243	        }
 9244	        // Braces inside a comment or a string literal are text, not structure:
 9245	        // one `// weird }` would close the test module early and let a
 9246	        // test-code anchor read as production (review of `e490671`).
 9247	        let structural = scanner.structural(source);
 9248	        depth += i32::try_from(structural.matches('{').count()).unwrap_or(0);
 9249	        depth -= i32::try_from(structural.matches('}').count()).unwrap_or(0);
 9250	        if in_test && depth <= test_depth && structural.contains('}') {
 9251	            in_test = false;
 9252	        }
 9253	    }
 9254	    false
 9255	}
