 9257	/// Brace counting that survives a line ending. Blind pass 1 at `ec045588`
 9258	/// (A07): the old per-line reader could not see a raw string or block comment
 9259	/// that spans lines, so their braces counted as structure — enough to hold a
 9260	/// `#[cfg(test)]` skip open past the module and hide a production spawn after
 9261	/// it. The state carries across lines, which is what a multi-line literal is.
 9262	///
 9263	/// A `'` opens a character literal only when it closes within one escape
 9264	/// sequence. Otherwise it introduces a lifetime, and reading `Formatter<'_>`
 9265	/// as an unterminated literal would swallow the `{` that follows it (F-56).
 9266	#[derive(Default)]
 9267	struct SourceScanner {
 9268	    in_block_comment: bool,
 9269	    /// Hashes of the raw string currently open, if one is.
