 9273	impl SourceScanner {
 9274	    /// `line` with its comments and literals removed, continuing whatever the
 9275	    /// previous line left open, so only braces that structure code remain.
 9276	    fn structural(&mut self, line: &str) -> String {
 9277	        let chars: Vec<char> = line.chars().collect();
 9278	        let mut out = String::with_capacity(line.len());
 9279	        let mut i = 0;
 9280	        while i < chars.len() {
 9281	            if self.in_block_comment {
 9282	                if chars[i] == '*' && chars.get(i + 1) == Some(&'/') {
 9283	                    self.in_block_comment = false;
 9284	                    i += 2;
 9285	                } else {
 9286	                    i += 1;
 9287	                }
 9288	                continue;
 9289	            }
 9290	            if let Some(hashes) = self.in_raw_string {
 9291	                let closes = chars[i] == '"'
 9292	                    && chars[i + 1..]
 9293	                        .iter()
 9294	                        .take(hashes)
 9295	                        .filter(|c| **c == '#')
 9296	                        .count()
 9297	                        == hashes;
 9298	                if closes {
 9299	                    self.in_raw_string = None;
 9300	                    i += 1 + hashes;
 9301	                } else {
 9302	                    i += 1;
 9303	                }
 9304	                continue;
 9305	            }
 9306	            if chars[i] == '/' && chars.get(i + 1) == Some(&'*') {
 9307	                self.in_block_comment = true;
 9308	                i += 2;
 9309	                continue;
 9310	            }
 9311	            if chars[i] == '/' && chars.get(i + 1) == Some(&'/') {
 9312	                break;
 9313	            }
 9314	            if let Some((hashes, after)) = raw_string_opening(&chars, i) {
 9315	                if let Some(end) = raw_string_close(&chars, after, hashes) {
 9316	                    i = end;
 9317	                    continue;
 9318	                }
 9319	                self.in_raw_string = Some(hashes);
 9320	                break;
 9321	            }
 9322	            if chars[i] == '"' {
 9323	                i = skip_string(&chars, i).max(i + 1);
 9324	                continue;
 9325	            }
 9326	            if let Some(after) = skip_char_literal(&chars, i) {
 9327	                i = after;
 9328	                continue;
 9329	            }
 9330	            out.push(chars[i]);
 9331	            i += 1;
 9332	        }
 9333	        out
 9334	    }
 9335	}
