 9337	/// The hash count and the index just past the opening quote of a raw string
 9338	/// starting at `at`, or `None` if one does not start there.
 9339	fn raw_string_opening(chars: &[char], at: usize) -> Option<(usize, usize)> {
 9340	    let mut i = at;
 9341	    if chars.get(i) == Some(&'b') {
 9342	        i += 1;
 9343	    }
 9344	    if chars.get(i) != Some(&'r') {
 9345	        return None;
 9346	    }
 9347	    i += 1;
 9348	    let hashes = chars[i..].iter().take_while(|c| **c == '#').count();
 9349	    i += hashes;
 9350	    if chars.get(i) != Some(&'"') {
 9351	        return None;
 9352	    }
 9353	    Some((hashes, i + 1))
 9354	}
