 9356	/// The index past a raw string's terminator, searching from `from`, or `None`
 9357	/// when the line ends inside it. Counted rather than `all`: on a tail shorter
 9358	/// than `hashes` an `all` is vacuously true, which would close the literal on
 9359	/// a quote that does not terminate it.
 9360	fn raw_string_close(chars: &[char], from: usize, hashes: usize) -> Option<usize> {
 9361	    let mut i = from;
 9362	    while i < chars.len() {
 9363	        if chars[i] == '"'
 9364	            && chars[i + 1..]
 9365	                .iter()
 9366	                .take(hashes)
 9367	                .filter(|c| **c == '#')
 9368	                .count()
 9369	                == hashes
 9370	        {
 9371	            return Some(i + 1 + hashes);
 9372	        }
 9373	        i += 1;
 9374	    }
 9375	    None
 9376	}
