 9378	/// The index past the string literal opening at `at`, or the end of the line.
 9379	fn skip_string(chars: &[char], at: usize) -> usize {
 9380	    let mut i = at + 1;
 9381	    while i < chars.len() {
 9382	        match chars[i] {
 9383	            '\\' => i += 2,
 9384	            '"' => return i + 1,
 9385	            _ => i += 1,
 9386	        }
 9387	    }
 9388	    chars.len()
 9389	}
