 9673	fn anchor_supports_operator(operator: &str, anchor: &str) -> bool {
 9674	    let trimmed = anchor.trim();
 9675	    let lower = trimmed.to_ascii_lowercase();
 9676	    let chars: Vec<char> = trimmed.chars().collect();
 9677	    let negation = chars.iter().enumerate().any(|(index, ch)| {
 9678	        *ch == '!'
 9679	            && chars.get(index + 1) != Some(&'=')
 9680	            && !index
 9681	                .checked_sub(1)
 9682	                .and_then(|prev| chars.get(prev))
 9683	                .is_some_and(|prev| prev.is_alphanumeric() || *prev == '_')
 9684	    });
 9685	    let integer = chars.iter().enumerate().any(|(index, ch)| {
 9686	        ch.is_ascii_digit()
 9687	            && !index
 9688	                .checked_sub(1)
 9689	                .and_then(|prev| chars.get(prev))
 9690	                .is_some_and(|prev| prev.is_alphanumeric() || *prev == '_')
 9691	    });
 9692	    let word = |needle: &str| {
 9693	        trimmed
 9694	            .split(|ch: char| !ch.is_alphanumeric() && ch != '_')
 9695	            .any(|token| token == needle)
 9696	    };
 9697	    match operator {
 9698	        // `|` is one of the contract's inversion pairs and must stay, but only
 9699	        // when it occurs once: a closure's `|m| ...` has two, and a generic's
 9700	        // `<` is excluded by requiring spaces, because inverting the `<` of
 9701	        // `Vec<String>` yields `Vec>=String>`, which is not a program.
 9702	        "predicate-inversion" => {
 9703	            // Blind pass 1 at `0a0b4b4b` (A04): a `|` in a PATTERN is an
 9704	            // alternative, not an operator — inverting the bar of
 9705	            // `A | B => ...` yields `A & B`, which is not a pattern and does
 9706	            // not compile, so the mutant could never be applied let alone
 9707	            // killed. A bar counts only where it can be bitwise or.
 9708	            let pattern_alternative = trimmed.contains("=>") || trimmed.starts_with('|');
 9709	            [
 9710	                "==", "!=", " <= ", " >= ", " < ", " > ", "&&", " true", " false",
 9711	            ]
 9712	            .iter()
 9713	            .any(|token| trimmed.matches(token).count() == 1)
 9714	                || has_disjunction(trimmed)
 9715	                || (!pattern_alternative && trimmed.matches('|').count() == 1)
 9716	        }
 9717	        "predicate-deletion" => negation,
 9718	        "threshold-plus-one" | "threshold-minus-one" => integer,
 9719	        "missing-enum-dispatch" => word("match"),
 9720	        "success-error-substitution" => trimmed.contains("Ok(") || trimmed.contains("Err("),
 9721	        "oracle-short-circuit" => {
 9722	            trimmed.contains("&&") || has_disjunction(trimmed) || trimmed == "if id.is_some() {"
 9723	        }
 9724	        "ordering-nondeterminism" => {
 9725	            trimmed.contains("sort")
 9726	                || trimmed.contains("BTree")
 9727	                || trimmed.starts_with("let lines: Vec<")
 9728	        }
 9729	        "stale-basis-acceptance" => {
 9730	            lower.contains("basis") || trimmed == "if rev == inner.state.head {"
 9731	        }
 9732	        "skipped-durable-transition" => DURABLE_CALL_MARKERS
 9733	            .iter()
 9734	            .any(|call| trimmed.contains(call)),
 9735	        "disabled-crash-point" => {
 9736	            lower.contains("crash")
 9737	                || trimmed == "if fail_after.is_some_and(|limit| committed >= limit) {"
 9738	        }
 9739	        "broadened-allow-list" => {
 9740	            word("match")
 9741	                || trimmed.contains("matches!")
 9742	                || trimmed.contains("ensure!")
 9743	                || trimmed.contains("=>")
 9744	        }
 9745	        "wrong-holder-selection" => WRONG_HOLDER_ANCHORS.contains(&trimmed),
 9746	        _ => false,
 9747	    }
 9748	}
