10513	    let elapsed_seconds: BTreeMap<&str, u64> = recorded
10514	        .iter()
10515	        .map(|row| (row.target.as_str(), row.elapsed_s))
10516	        .collect();
10517	    let mut total_minutes = 0_u64;
10518	    for family in declared {
