 11078	fn durable_transition_sites(root: &Utf8Path) -> Result<BTreeMap<String, usize>> {
 11079	    // Blind pass 1 at 612cbcc (A05): `inner.log.append(` is the store's durable
 11080	    // append (P1-M022 deletes it) and was outside the census, so an append-based
 11081	    // transition could move without the scope disclosure noticing.
 11082	    // Blind pass 1 at f360e90 (A05): a direct `fs::rename` or `sync_all` is a
 11083	    // durable transition with no marker call around it, so it escaped.
 11084	    // Blind pass 1 at aa00d41 (A05): `use std::fs::rename as mv; mv(a, b)`
 11085	    // named no marker. The durable symbols are matched by name, and a `use`
 11086	    // that renames one adds its alias for that file.
 11087	    const DURABLE_SYMBOLS: [&str; 6] = [
 11088	        "commit",
 11089	        "commit_if",
 11090	        "append",
 11091	        "sync_all",
 11092	        "sync_data",
 11093	        "rename",
 11094	    ];
 11095	    let listed = git_text(root, &["ls-files", "-z", "--", "crates"])?;
 11096	    let mut sites = BTreeMap::new();
 11097	    for name in listed.split('\0').filter(|name| !name.trim().is_empty()) {
 11098	        if Utf8Path::new(name).extension() != Some("rs")
 11099	            || name.starts_with("crates/liminal-xtask/")
 11100	            || name.contains("/tests/")
 11101	        {
 11102	            continue;
 11103	        }
 11104	        let path = root.join(name);
 11105	        // Never skip a tracked file we cannot read. Dropping it would delete
 11106	        // its transitions from the measured surface, and the disclosure would
 11107	        // then pass by describing a tree nobody managed to look at — the exact
 11108	        // vacuity this check exists to prevent.
 11109	        let text = fs::read_to_string(&path).with_context(|| {
 11110	            format!(
 11111	                "{name} is tracked but unreadable; the durable surface cannot be measured, and \
 11112	                 a scope claim over a surface that was not read is worth nothing"
 11113	            )
 11114	        })?;
 11115	        // A `use` that renames a durable symbol makes the alias a marker in
 11116	        // this file: `use std::fs::rename as mv;` means `mv` is a rename.
 11117	        let mut markers = DURABLE_SYMBOLS
 11118	            .iter()
 11119	            .map(|symbol| (*symbol).to_owned())
 11120	            .collect::<Vec<_>>();
 11121	        for line in text.lines() {
 11122	            for (symbol, alias) in use_aliases(line) {
 11123	                if DURABLE_SYMBOLS.contains(&symbol.as_str()) {
 11124	                    markers.push(alias);
 11125	                }
 11126	            }
 11127	        }
 11128	        let count = text
 11129	            .lines()
 11130	            // An import declares a name; it performs no transition. Without
 11131	            // this the aliasing `use` line counts as a durable call itself.
 11132	            .filter(|line| {
 11133	                let trimmed = line.trim_start();
 11134	                !trimmed.starts_with("//") && !trimmed.starts_with("use ")
 11135	            })
 11136	            .map(|line| durable_symbol_hits(line, &markers))
 11137	            .sum::<usize>();
 11138	        if count > 0 {
 11139	            sites.insert(name.to_owned(), count);
 11140	        }
 11141	    }
 11142	    Ok(sites)
 11143	}
