7182	        // partial set, and a hard link to a file inside it would then pass. A
7183	        // corpus this cannot enumerate is a corpus it cannot protect.
7184	        let entries = fs::read_dir(dir.as_std_path())
7185	            .with_context(|| format!("enumerate the locked corpus at {dir}"))?;
7186	        for entry in entries.flatten() {
7187	            let path = entry.path();
7188	            let metadata = fs::symlink_metadata(&path)
7189	                .with_context(|| format!("stat {} in the locked corpus", path.display()))?;
