11749	                            .push(format!("{relative}:{}:{token}", index + 1));
11750	                    }
11751	                }
11752	                for token in CONCURRENCY_SYNC_PRIMITIVES {
11753	                    if line.contains(token) {
11754	                        scan.sync.push(format!("{relative}:{}:{token}", index + 1));
11755	                    }
11756	                }
11757	            }
11758	        }
11759	    }
11760	    Ok(scan)

