11590	fn runtime_external_dependencies(manifest: &Utf8Path) -> Result<BTreeSet<String>> {
11591	    let text = fs::read_to_string(manifest).with_context(|| format!("read {manifest}"))?;
11592	    let mut section = String::new();
11593	    let mut out = BTreeSet::new();
11594	    for line in text.lines() {
11595	        let trimmed = line.trim();
11596	        if let Some(name) = trimmed.strip_prefix('[').and_then(|r| r.strip_suffix(']')) {
11597	            section.clear();
11598	            section.push_str(name);
11599	            continue;
11600	        }
11601	        let last = section.rsplit('.').next().unwrap_or_default();
11602	        if last != "dependencies" || section.contains("dev-") || section.contains("build-") {
11603	            continue;
11604	        }
11605	        let Some((key, _)) = trimmed.split_once('=') else {
11606	            continue;
11607	        };
11608	        let key = key.trim().trim_matches('"');
11609	        // `serde.workspace = true` names the crate before the dot.
11610	        let key = key.split('.').next().unwrap_or(key);
11611	        if key.is_empty() || key.starts_with('#') || key.starts_with("liminal") {
11612	            continue;
11613	        }
11614	        out.insert(key.to_owned());
11615	    }
11616	    Ok(out)
11617	}
